/* Read-only visual projections of real records. Controls navigate to the existing editors. */
window.WorkshopSystems=(()=>{
  const titles={blueprint:['01 / SYSTEMS ARCHITECTURE','Configuration circuit'],laboratory:['02 / DIAGNOSTICS','Signal observatory'],roster:['03 / OPERATOR DIRECTORY','Persistent identities'],queue:['04 / MISSION OPERATIONS','Dispatch board'],sessions:['05 / CONTEXT VAULT','Knowledge continuity'],learn:['06 / TRAINING TERMINAL','Briefing room'],settings:['07 / ENVIRONMENT CONTROL','Workspace configuration']};
  const focus=(selector,title,value)=>`<button class="system-node" data-system-focus='${selector}'><small>${title}</small><strong>${value}</strong><span>Inspect ↗</span></button>`;
  const link=(view,title,value)=>`<button class="system-node" data-view="${view}"><small>${title}</small><strong>${value}</strong><span>Open ↗</span></button>`;
  function render(view,s,a,esc){if(!titles[view])return '';const t=titles[view],runs=s.runs.filter(r=>r.agentId===a.id),events=s.runs.flatMap(r=>r.events),session=s.sessions.find(x=>x.id===a.sessionId);let body='';
    if(view==='blueprint')body=`<div class="system-circuit">${focus('[name="instructions"]','OPERATOR · '+esc(a.name),'v'+a.version+' / instructions')}${focus('[name="tool"]','PERMISSION / INPUT',a.tool?'Document · read only':'Document · disabled')}${focus('.advanced-fields','PROVIDER','Fixed simulation')}${link('laboratory','OUTPUT / OBSERVABILITY',runs.length+' recorded tasks')}</div><p class="system-caption">Solid connections show the implemented extraction path. Select a node to inspect its configuration. Provider selection and editable orchestration graphs remain future integrations.</p>`;
    if(view==='laboratory'){const types=[['Tools',events.filter(e=>e.type.startsWith('tool.')).length],['Results',events.filter(e=>e.type==='task.completed').length],['Errors',s.runs.filter(r=>r.status==='failed').length],['Handoffs',s.handoffs.length],['Spatial events',s.space.events.length]],max=Math.max(1,...types.map(x=>x[1]));body=`<div class="diagnostic-bars" role="img" aria-label="Recorded event counts">${types.map(([name,n])=>`<div><span>${name}</span><i style="--measure:${n/max*100}%"></i><b>${n}</b></div>`).join('')}</div><p class="system-caption">Counts from stored records across all operators. Spatial history retains the latest 500 events. Expand the shared timeline below for payloads; choose a run for output, errors and evaluation.</p>`;}
    if(view==='queue'){const groups=[['queued','Queued'],['active','Running / paused'],['waiting','Approval'],['completed','Completed'],['failed','Failed / cancelled']];body=`<div class="dispatch-board">${groups.map(([key,name])=>{const list=s.runs.filter(r=>key==='active'?['working','using-tool','paused'].includes(r.status):key==='failed'?['failed','cancelled'].includes(r.status):r.status===key);return `<section><h3>${name} <b>${list.length}</b></h3>${list.slice(0,4).map(r=>`<button class="dispatch-ticket" data-select-agent="${r.agentId}"><small>${esc(s.agents.find(a=>a.id===r.agentId)?.name)}</small><strong>${esc(r.task)}</strong><span>${esc(r.status)} · v${r.config.version}</span></button>`).join('')||'<p>Clear</p>'}${list.length>4?`<small>+ ${list.length-4} more in agent history</small>`:''}</section>`;}).join('')}</div><p class="system-caption">Select an assignment to open that operator’s queue controls below. Running work stops when this page closes.</p>`;}
    if(view==='sessions')body=`<div class="system-circuit">${link('blueprint','PERSISTENT IDENTITY',esc(a.name)+' · v'+a.version)}${focus('[data-session="fresh"]','ACTIVE SESSION',esc(session?.title||'Session'))}${focus('#memory-form textarea','INTENTIONAL MEMORY',s.memories.filter(m=>m.agentId===a.id).length+' saved entries')}${link('laboratory','EXECUTION ARCHIVE',runs.length+' recorded tasks')}</div><div class="context-strip"><b>${session?.context.length||0} explicitly attached context items</b><span>${s.sessions.filter(x=>x.agentId===a.id).length} saved sessions · token use not applicable in simulation</span></div>`;
    if(view==='roster')body=`<div class="directory-summary">${['active','resting','archived'].map(l=>`<div><strong>${s.agents.filter(a=>a.lifecycle===l).length}</strong><span>${l} operators</span></div>`).join('')}</div><p class="system-caption">Configuration, appearance, sessions and history belong to the operator. Rest and archive preserve that identity; duplication creates a separate one.</p>`;
    if(view==='learn')body=`<div class="system-circuit">${link('workshop','01 / LEARN BY DOING','Guided workshop')}${link('blueprint','02 / CONFIGURE','Instructions & tools')}${link('laboratory','03 / OBSERVE','Trace & evaluation')}${link('sessions','04 / CONTINUE','Context & memory')}</div><p class="system-caption">Use the lessons below to revisit any action. Skip, exit and reset controls preserve personal agents.</p>`;
    if(view==='settings')body=`<div class="system-circuit">${focus('#theme-select','VISUAL ENVIRONMENT','Three shared themes')}${link('sessions','STORAGE','Local browser only')}${link('workshop','EXECUTION','Simulation · $0 API spend')}</div>`;
    return `<section class="system-terminal system-${view}" aria-label="${t[1]}"><header><span class="eyebrow">${t[0]}</span><h2>${t[1]}</h2><span class="terminal-status">● LOCAL / SIMULATION</span></header>${body}</section>`;
  }return {render};
})();
